const D = { energy: .6, scale: 1, speed: 1, density: .5, load: .55, polar: .3, hue: 300, x: .5, y: .5, style: 'isochromatic', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Photoelasticity: white light through a stressed birefringent medium between crossed
// polarizers. The stress tensor comes from an Airy stress function phi (any phi satisfies
// equilibrium exactly): sxx = d2phi/dy2, syy = d2phi/dx2, sxy = -d2phi/dxdy.
// Retardation is proportional to the principal stress DIFFERENCE, so
//   I(lambda) = sin^2( pi * C * (s1-s2) / lambda )
// summed over R/G/B gives the true isochromatic fringe colour sequence; the isoclinic
// factor sin^2(2(theta - polAng)) puts the black bands where a principal axis lines up
// with the polarizer. ----
const BW = 176, BH = Math.max(72, Math.round(BW * height / width));
const N = BW * BH;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.PH = new Float32Array(N);
}

const sd = P.seed | 0;
function hsh(ix, iy, iz) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(iz, 1274126177) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;   // >>> not >> : an arithmetic fold caps the hash at 0.5
}
function vn3(x, y, z) {
  const ix = Math.floor(x), iy = Math.floor(y), iz = Math.floor(z);
  const fx = x - ix, fy = y - iy, fz = z - iz;
  const u = fx * fx * (3 - 2 * fx), v = fy * fy * (3 - 2 * fy), w = fz * fz * (3 - 2 * fz);
  const a0 = hsh(ix, iy, iz), a1 = hsh(ix + 1, iy, iz), a2 = hsh(ix, iy + 1, iz), a3 = hsh(ix + 1, iy + 1, iz);
  const b0 = hsh(ix, iy, iz + 1), b1 = hsh(ix + 1, iy, iz + 1), b2 = hsh(ix, iy + 1, iz + 1), b3 = hsh(ix + 1, iy + 1, iz + 1);
  const x00 = a0 + (a1 - a0) * u, x10 = a2 + (a3 - a2) * u, x01 = b0 + (b1 - b0) * u, x11 = b2 + (b3 - b2) * u;
  const y0 = x00 + (x10 - x00) * v, y1 = x01 + (x11 - x01) * v;
  return y0 + (y1 - y0) * w;
}
function fbm3(x, y, z) { return 0.58 * vn3(x, y, z) + 0.27 * vn3(x * 2.13 + 5.1, y * 2.13 - 3.2, z * 1.6 + 1.3) + 0.15 * vn3(x * 4.31 - 2.3, y * 4.31 + 7.7, z * 2.7 - 4.1); }

const tt = K.t;
const sp2 = 0.25 + P.speed * 0.9;
// Master drift rate. A fringe field is inherently high-variance: any change to the stress
// sweeps whole bands, so the 8s motion metric runs hot and crowds the 0.35 strobe ceiling.
// The specimen is meant to be loaded and relaxed over MINUTES — slow is both the fix and the
// intent. EV scales every drift rate in the piece at once.
const EV = 0.24;

// ---- build the Airy stress function on the grid ----
const nL = 2 + Math.round(P.density * 4);      // discrete load points pressing on the specimen
const zf = tt * 0.013 * EV * sp2 + 7.3;
const fsp = 2.3 / BH;
const ox = 0.8 * Math.sin(tt * 0.041 * EV) + 0.35 * Math.sin(tt * 0.103 * EV + 1.6);
const oy = 0.6 * Math.cos(tt * 0.059 * EV) + 0.3 * Math.sin(tt * 0.127 * EV + 0.8);
const PH = S.PH;
// load points orbit slowly; each contributes a smooth Airy-like well -> stress concentrations
const lx = [], ly = [], lw = [];
for (let s = 0; s < nL; s++) {
  const a1 = 0.19 + hsh(s * 7 + 1, 2, 6) * 0.5, a2 = 0.17 + hsh(s * 7 + 2, 3, 6) * 0.44;
  const b1 = hsh(s * 7 + 3, 4, 6) * 6.28, b2 = hsh(s * 7 + 4, 5, 6) * 6.28;
  lx.push((0.5 + 0.40 * Math.sin(tt * a1 * 0.052 * EV * sp2 + b1)) * BW);
  ly.push((0.5 + 0.38 * Math.cos(tt * a2 * 0.047 * EV * sp2 + b2)) * BH);
  lw.push((0.5 + 0.5 * Math.sin(tt * (0.021 + s * 0.009) * EV + s * 1.9)) * 2 - 0.6);
}
const ls = BH * 0.30;
for (let j = 0; j < BH; j++) {
  for (let i = 0; i < BW; i++) {
    let v = fbm3(i * fsp + ox, j * fsp + oy, zf) * 1.9;
    for (let s = 0; s < nL; s++) {
      const dx = (i - lx[s]) / ls, dy = (j - ly[s]) / ls;
      const rr = dx * dx + dy * dy;
      v += lw[s] * Math.exp(-rr * 1.6) * 1.5;    // smooth load well
    }
    PH[j * BW + i] = v;
  }
}

// ---- render: second derivatives of phi -> stress tensor -> fringes ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const sec = K.section | 0;
const style = P.style;
const hb = ((P.hue + sec * 14) % 360 + 360) % 360;
// the specimen is slowly LOADED and unloaded over minutes: fringe order climbs and crowds in,
// then relaxes. Incommensurate sines, so the frame never repeats.
const loadArc = 0.76 + 0.15 * Math.sin(tt * 0.0217 * EV) + 0.08 * Math.sin(tt * 0.0463 * EV + 2.1) + 0.04 * Math.sin(tt * 0.0791 * EV + 0.7);
// The stress difference off a smooth Airy function's second differences is ~5e-3, so the
// stress-optic constant has to be ~1e3 for the retardation to reach the several fringe
// ORDERS that make the colour sequence read. At C~70 the whole plate is black.
const C = (150 + P.load * 620) * loadArc * (0.88 + K.swell * 0.08 + A.lowmid * 0.20);
const gain = 0.5 + P.energy * 1.1 + A.rms * 0.35;
// polarizer angle: sweeps the black isoclinic bands across the frame (slow — never a strobe)
const polAng = P.polar * 3.1416 + tt * 0.0105 * EV;
// R/G/B relative wavelengths (610 / 545 / 460 nm, normalised) — this ratio IS the photoelastic
// colour sequence: straw -> magenta -> blue-green -> ...
const wR = 1.0, wG = 0.893, wB = 0.754;
function pal(m, spx, off) {
  const hr = hb / 360 + off;
  return [0.5 + 0.5 * Math.cos(6.2831 * (m + hr)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr + spx)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr + spx * 2))];
}
for (let j = 0; j < BH; j++) {
  const jm = (j > 0 ? j - 1 : 0) * BW, jp = (j < BH - 1 ? j + 1 : BH - 1) * BW, jc = j * BW;
  const jm2 = (j > 1 ? j - 1 : 0), jp2 = (j < BH - 1 ? j + 1 : BH - 1);
  for (let i = 0; i < BW; i++) {
    const im = i > 0 ? i - 1 : 0, ip = i < BW - 1 ? i + 1 : BW - 1;
    const c0 = PH[jc + i];
    // second derivatives of the Airy function -> the stress tensor
    const sxx = PH[jp + i] + PH[jm + i] - 2 * c0;            // d2phi/dy2
    const syy = PH[jc + ip] + PH[jc + im] - 2 * c0;          // d2phi/dx2
    const sxy = -(PH[jp2 * BW + ip] - PH[jp2 * BW + im] - PH[jm2 * BW + ip] + PH[jm2 * BW + im]) * 0.25;
    const dif = sxx - syy;
    const R2 = Math.sqrt(dif * dif + 4 * sxy * sxy);         // principal stress difference s1-s2
    const theta = 0.5 * Math.atan2(2 * sxy, dif);            // principal axis direction
    const delta = R2 * C;                                     // retardation
    // Isoclinic factor. theta is the PRINCIPAL STRESS DIRECTION, which wanders wildly wherever
    // R2 is small, so sin^2(2(theta-polAng)) is a noisy full-range multiplier — as a global
    // gain it churns the whole plate. A real lab hits exactly this and answers with a CIRCULAR
    // polariscope: quarter-wave plates delete the isoclinics and leave pure isochromatics.
    // So the fringe styles run circular (isoc = 1) and only `isoclinic` runs a plane polariscope.
    const iso = Math.sin(2 * (theta - polAng));
    const isoP = iso * iso;
    const isoc = 0.5 + 0.5 * isoP;
    let r, gg, b;
    if (style === 'monochromatic') {        // sodium lamp (589nm): one wavelength, pure dark/bright fringes
      const s1 = Math.sin(delta * 0.5 / 0.965); const I = Math.pow(s1 * s1 * isoc, 0.72);
      const v = Math.min(1, I * (0.42 + gain * 0.48) + 0.04);
      r = v * 1.0; gg = v * 0.86; b = v * 0.22;
    } else if (style === 'isoclinic') {     // plane polariscope: only the black isoclinic bands sweep
      const v = Math.min(1, isoP * (0.55 + gain * 0.5) * 0.8 + 0.08);
      const cc = pal(0.5 + R2 * 0.04, 0.1, 0.0);
      r = Math.min(1, v * (0.42 + cc[0] * 0.5)); gg = Math.min(1, v * (0.44 + cc[1] * 0.5)); b = Math.min(1, v * (0.5 + cc[2] * 0.5));
    } else if (style === 'stress_map') {    // clinical FEA plot of the stress magnitude — no fringes
      const m = Math.min(1, R2 * C * 0.052 * (0.55 + gain * 0.5));
      const cc = pal(0.02 + m * 0.62, 0.28, 0.0);
      const sh = 0.20 + m * 0.85;
      r = Math.min(1, cc[0] * sh); gg = Math.min(1, cc[1] * sh); b = Math.min(1, cc[2] * sh);
    } else if (style === 'xray') {          // dark-field: fringes as luminous filaments, no colour
      const s1 = Math.sin(delta * 0.5); const I = s1 * s1 * (0.45 + 0.55 * isoP);
      const v = Math.pow(I, 1.6) * (0.7 + gain * 0.6);
      r = Math.min(1, v * 0.86 + 0.055); gg = Math.min(1, v * 0.94 + 0.065); b = Math.min(1, v * 1.0 + 0.09);
    } else {                                // isochromatic (default) — white-light fringes
      const sR = Math.sin(delta * 0.5 / wR), sG = Math.sin(delta * 0.5 / wG), sB = Math.sin(delta * 0.5 / wB);
      const k = (0.38 + gain * 0.40);
      r = Math.min(1, sR * sR * isoc * k + 0.035);
      gg = Math.min(1, sG * sG * isoc * k + 0.04);
      b = Math.min(1, sB * sB * isoc * k + 0.06);
    }
    const o = 4 * (jc + i);
    px[o] = Math.max(0, Math.min(255, r * 255));
    px[o + 1] = Math.max(0, Math.min(255, gg * 255));
    px[o + 2] = Math.max(0, Math.min(255, b * 255));
    px[o + 3] = 255;
  }
}
g.updatePixels();

const z = Math.max(1, P.scale);
const sw = BW / z, sh = BH / z;
const sx = (BW - sw) * Math.min(1, Math.max(0, P.x)), sy = (BH - sh) * Math.min(1, Math.max(0, P.y));
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height, sx, sy, sw, sh);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
